//! Read generated bytes and literal manifests without invoking their generators.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::ops::Range;
use std::path::Path;

use base64::Engine as _;
use serde_json::{Value, json};

use super::verification_domain::{self as domain, Spec};
use super::{STANDARD, interval, private, sha256_bytes, verification_details};

pub(super) fn field<'a>(value: &'a Value, name: &str) -> Result<&'a Value, String> {
    value
        .as_object()
        .and_then(|object| object.get(name))
        .ok_or_else(|| format!("missing required field {name}"))
}

pub(super) fn require_fields(value: &Value, names: &[&str]) -> Result<(), String> {
    for name in names {
        field(value, name)?;
    }
    Ok(())
}

pub(super) fn number(value: &Value) -> Result<usize, String> {
    usize::try_from(
        value
            .as_u64()
            .ok_or("missing nonnegative manifest integer")?,
    )
    .map_err(|_| "manifest integer exceeds this host".into())
}

pub(super) fn range(value: &Value, limit: usize) -> Result<Range<usize>, String> {
    let start = number(&value["start"])?;
    let end = number(&value["end"])?;
    if start > end || end > limit {
        return Err("manifest interval exceeds its byte stream".into());
    }
    Ok(start..end)
}

/// Walk bytes once in order, incrementing the physical row/column counters.
/// This does not use the generator's newline index or binary-search algorithm.
pub(super) fn walk_positions(
    bytes: &[u8],
    offsets: impl IntoIterator<Item = usize>,
) -> Result<BTreeMap<usize, (usize, usize)>, String> {
    let mut positions = BTreeMap::new();
    let mut cursor = 0;
    let mut line = 1;
    let mut column = 1;
    for offset in offsets.into_iter().collect::<BTreeSet<_>>() {
        let segment = bytes
            .get(cursor..offset)
            .ok_or("coordinate offset exceeds input")?;
        for byte in segment {
            if *byte == b'\n' {
                line += 1;
                column = 1;
            } else {
                column += 1;
            }
        }
        positions.insert(offset, (line, column));
        cursor = offset;
    }
    Ok(positions)
}

fn position(positions: &BTreeMap<usize, (usize, usize)>, span: &Range<usize>) -> Value {
    let (start_line, start_column) = positions[&span.start];
    let (end_line, end_column) = positions[&span.end];
    json!({
        "start": {"line": start_line, "byte_column": start_column},
        "end_exclusive": {"line": end_line, "byte_column": end_column}
    })
}

#[cfg(test)]
pub(super) fn verify_bytes(input: &[u8], manifest: &Value) -> Result<(), String> {
    let family = manifest["family"]
        .as_str()
        .ok_or("missing manifest family")?;
    let id = manifest["id"].as_str().ok_or("missing manifest id")?;
    let specs = domain::required_cases(domain::command_family(family)?)?;
    let spec = *specs
        .get(id)
        .ok_or("manifest id is outside its declared family domain")?;
    verify_case(input, manifest, spec)
}

fn verify_case(input: &[u8], manifest: &Value, spec: Spec) -> Result<(), String> {
    require_fields(
        manifest,
        &[
            "schema",
            "id",
            "family",
            "partition",
            "expected_canonical_family",
            "expectation_scope",
            "rule_identity_contract",
            "input_path",
            "input_bytes",
            "input_sha256",
            "plaintext_sha256",
            "decode_depth",
            "physical_source_encoded_carrier_bytes",
            "encoding_layers",
            "plants",
            "expected_occurrences",
            "expected_unique_values",
            "literal_planted_values",
            "result_requirement",
            "timing_eligible_after_scope_and_quality_gate",
            "coordinate_contract",
            "details",
        ],
    )?;
    if manifest["schema"] != "rustleaks.development-fixture.v1"
        || number(&manifest["input_bytes"])? != input.len()
        || manifest["input_sha256"] != sha256_bytes(input)
        || manifest["family"] != spec.family()
        || manifest["partition"] != "development"
    {
        return Err("input identity differs from its construction manifest".into());
    }
    let connection = matches!(spec, Spec::Connection { .. });
    let required_policy = if connection {
        "policy-review-required-before-scoring"
    } else {
        "complete-with-exact-planted-occurrences"
    };
    let scope = if connection {
        "unscored-connection-policy-proposal"
    } else {
        "declared-canonical-family-only; unrelated-native-findings-are-not-rejected"
    };
    if manifest["result_requirement"] != required_policy
        || manifest["expectation_scope"] != scope
        || manifest["rule_identity_contract"]
            != "retain-native-identifiers; canonical-family-mapping-requires-an-audited-profile-map"
        || manifest["expected_canonical_family"]
            != if connection {
                Value::Null
            } else {
                json!("github-pat")
            }
    {
        return Err("fixture result policy or canonical-family scope differs".into());
    }
    if manifest["coordinate_contract"]["intervals"] != "zero-based-half-open-physical-byte-offsets"
        || manifest["coordinate_contract"]["positions"]
            != "one-based-lines-and-byte-columns-LF-delimited"
        || manifest["coordinate_contract"]["legacy_columns"]
            != "not-the-physical-oracle; validate-legacy-coordinates-separately"
        || manifest["coordinate_contract"]["decoded_public_byte_ranges"]
            != "unavailable; retain-inner-and-outer-construction-spans-separately"
    {
        return Err("fixture coordinate contract differs".into());
    }
    let depth = number(&manifest["decode_depth"])?;
    if depth > 2 {
        return Err("fixture decode depth exceeds the declared generator domain".into());
    }
    let layers = manifest["encoding_layers"]
        .as_array()
        .ok_or("missing layer inventory")?;
    if layers.len() != depth {
        return Err("encoding layer count differs".into());
    }
    let mut plaintext = input.to_vec();
    let outer = if depth > 0 {
        let outer = range(
            &manifest["physical_source_encoded_carrier_bytes"],
            input.len(),
        )?;
        plaintext = input[outer.clone()].to_vec();
        for layer in layers.iter().rev() {
            plaintext = STANDARD
                .decode(&plaintext)
                .map_err(|_| "invalid constructed Base64 layer")?;
            if layer["sha256"] != sha256_bytes(&plaintext)
                || number(&layer["bytes"])? != plaintext.len()
            {
                return Err("decoded layer identity differs".into());
            }
        }
        Some(outer)
    } else {
        if !manifest["physical_source_encoded_carrier_bytes"].is_null() {
            return Err("unencoded fixture claims an encoded carrier".into());
        }
        None
    };
    if manifest["plaintext_sha256"] != sha256_bytes(&plaintext) {
        return Err("plaintext identity differs".into());
    }
    let plants = manifest["plants"]
        .as_array()
        .ok_or("missing literal plants")?;
    let mut literals = Vec::new();
    let mut input_offsets = Vec::new();
    let mut plaintext_offsets = Vec::new();
    for plant in plants {
        require_fields(
            plant,
            &[
                "ordinal",
                "value",
                "value_sha256",
                "plaintext_secret_bytes",
                "plaintext_carrier_bytes",
                "physical_source_secret_bytes",
                "physical_source_carrier_bytes",
                "plaintext_position",
                "source_carrier_position",
            ],
        )?;
        let span = range(&plant["plaintext_secret_bytes"], plaintext.len())?;
        let carrier = range(&plant["plaintext_carrier_bytes"], plaintext.len())?;
        let physical = outer.as_ref().unwrap_or(&carrier);
        plaintext_offsets.extend([span.start, span.end]);
        input_offsets.extend([physical.start, physical.end]);
    }
    let input_positions = walk_positions(input, input_offsets)?;
    let plaintext_positions = walk_positions(&plaintext, plaintext_offsets)?;
    for (ordinal, plant) in plants.iter().enumerate() {
        let value = plant["value"]
            .as_str()
            .ok_or("missing literal value")?
            .as_bytes();
        let span = range(&plant["plaintext_secret_bytes"], plaintext.len())?;
        let carrier = range(&plant["plaintext_carrier_bytes"], plaintext.len())?;
        let physical = outer.as_ref().unwrap_or(&carrier);
        if ordinal != number(&plant["ordinal"])?
            || plaintext.get(span.clone()) != Some(value)
            || plant["value_sha256"] != sha256_bytes(value)
            || carrier.start > span.start
            || carrier.end < span.end
            || !connection && carrier != span
            || plant["physical_source_carrier_bytes"] != interval(physical)
            || plant["plaintext_position"] != position(&plaintext_positions, &span)
            || plant["source_carrier_position"] != position(&input_positions, physical)
        {
            return Err("literal plant bytes or physical coordinates differ".into());
        }
        if outer.is_some() {
            if !plant["physical_source_secret_bytes"].is_null() {
                return Err("decoded secret falsely claims a raw source interval".into());
            }
        } else if plant["physical_source_secret_bytes"] != interval(&span) {
            return Err("raw secret source interval differs".into());
        }
        literals.push((span.start, value.to_vec()));
    }
    if number(&manifest["literal_planted_values"])? != literals.len() {
        return Err("literal plant count differs".into());
    }
    match manifest["result_requirement"].as_str() {
        Some("complete-with-exact-planted-occurrences") => {
            let actual = plaintext
                .windows(40)
                .enumerate()
                .filter(|(_, value)| {
                    value.starts_with(b"ghp_") && value[4..].iter().all(u8::is_ascii_alphanumeric)
                })
                .map(|(start, value)| (start, value.to_vec()))
                .collect::<Vec<_>>();
            let unique = literals
                .iter()
                .map(|(_, value)| value)
                .collect::<BTreeSet<_>>()
                .len();
            if actual != literals
                || number(&manifest["expected_occurrences"])? != literals.len()
                || number(&manifest["expected_unique_values"])? != unique
            {
                return Err(
                    "literal grammar census differs from declared occurrence identities".into(),
                );
            }
        }
        Some("policy-review-required-before-scoring") => {
            if !manifest["expected_occurrences"].is_null()
                || !manifest["expected_unique_values"].is_null()
            {
                return Err("unreviewed policy has assigned pass expectations".into());
            }
        }
        _ => return Err("unknown fixture result requirement".into()),
    }
    verification_details::verify(spec, input, &plaintext, manifest)
}

pub(super) fn verify_inventory(inventory: &Value) -> Result<BTreeMap<String, Spec>, String> {
    require_fields(
        inventory,
        &[
            "schema",
            "development_seed",
            "seed_recipe",
            "alphabet",
            "family",
            "domain",
            "partition",
            "logical_case_count",
            "distinct_input_count",
            "reader_schedule_expectations",
            "cases",
            "scanners_invoked",
            "measurements_run",
            "construction_only",
            "input_scope",
        ],
    )?;
    let family = inventory["family"]
        .as_str()
        .ok_or("missing inventory family")?;
    let required = domain::required_cases(family)?;
    for spec in required.values() {
        if domain::command_family(spec.family())? != family {
            return Err("verifier matrix contains an inconsistent family".into());
        }
    }
    let (logical, distinct, schedules) = domain::counts(family)?;
    if inventory["schema"] != "rustleaks.development-fixtures.v1"
        || inventory["domain"] != "full-family-v1"
        || inventory["partition"] != "development"
        || inventory["development_seed"] != "rustleaks.kingfisher-expansion.v1.dev.2026-11-13"
        || inventory["alphabet"] != "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
        || inventory["seed_recipe"]
            != "SHA256(seed || NUL || family || NUL || development || NUL || decimal-ordinal || NUL || decimal-counter); reject bytes >= 248; map accepted bytes modulo 62"
        || number(&inventory["logical_case_count"])? != logical
        || number(&inventory["distinct_input_count"])? != distinct
        || number(&inventory["reader_schedule_expectations"])? != schedules
        || inventory["scanners_invoked"] != false
        || inventory["measurements_run"] != false
        || inventory["construction_only"] != true
        || inventory["input_scope"]
            != "each inputs/<case>/ directory independently; never scan the bundle root or answers"
    {
        return Err(
            "inventory fixed domain, seed, counts, or construction contract differs".into(),
        );
    }
    let cases = inventory["cases"]
        .as_array()
        .ok_or("missing case inventory")?;
    let mut ids = BTreeSet::new();
    let mut hashes = BTreeSet::new();
    for case in cases {
        require_fields(
            case,
            &[
                "id",
                "input_sha256",
                "input_bytes",
                "expected_occurrences",
                "manifest_path",
                "manifest_sha256",
            ],
        )?;
        let id = case["id"].as_str().ok_or("missing case id")?;
        let hash = case["input_sha256"].as_str().ok_or("missing input hash")?;
        if !ids.insert(id)
            || !required.contains_key(id)
            || hash.len() != 64
            || !hash
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        {
            return Err(
                "inventory has duplicate or undeclared cases or invalid input identities".into(),
            );
        }
        if field(case, "expected_occurrences")? != &json!(required[id].expected_occurrences()) {
            return Err(
                "inventory expected occurrence policy differs from its fixed case specification"
                    .into(),
            );
        }
        hashes.insert(hash);
    }
    if ids.len() != logical || hashes.len() != distinct {
        return Err("inventory lacks required cases or distinct byte inputs".into());
    }
    Ok(required)
}

pub(super) fn run(root: &Path) -> Result<(), String> {
    if !root.is_absolute() {
        return Err("verification requires an absolute fixture directory".into());
    }
    private::checked_path(root)?;
    let inventory = private::read_json(&root.join("inventory.json"))?;
    let specs = verify_inventory(&inventory)?;
    let cases = inventory["cases"]
        .as_array()
        .ok_or("missing case inventory")?;
    let mut ids = BTreeSet::new();
    let mut pairs = BTreeMap::new();
    for case in cases {
        let id = case["id"].as_str().ok_or("missing case id")?;
        if id.is_empty()
            || !id
                .bytes()
                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
            || !ids.insert(id)
        {
            return Err("duplicate or unsafe fixture id".into());
        }
        let manifest_path = format!("answers/{id}.json");
        let input_path = format!("inputs/{id}/input.txt");
        if case["manifest_path"] != manifest_path {
            return Err("manifest path differs from its case identity".into());
        }
        let manifest_path = root.join(manifest_path);
        // The largest dense manifest has 32768 literal events with coordinates.
        private::regular_file(&manifest_path, 128 * 1024 * 1024)?;
        let bytes = fs::read(manifest_path).map_err(|error| error.to_string())?;
        if case["manifest_sha256"] != sha256_bytes(&bytes) {
            return Err("manifest file hash differs from inventory".into());
        }
        let manifest: Value = serde_json::from_slice(&bytes).map_err(|error| error.to_string())?;
        if manifest["id"] != id
            || manifest["input_path"] != input_path
            || manifest["input_sha256"] != case["input_sha256"]
            || manifest["input_bytes"] != case["input_bytes"]
            || manifest["expected_occurrences"] != case["expected_occurrences"]
        {
            return Err("manifest identity differs from inventory".into());
        }
        let input_path = root.join(input_path);
        let directory = input_path.parent().ok_or("input lacks parent directory")?;
        let entries = fs::read_dir(directory)
            .map_err(|error| error.to_string())?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| error.to_string())?;
        if entries.len() != 1 || entries[0].file_name() != "input.txt" {
            return Err("case scan directory contains unexpected input files".into());
        }
        private::regular_file(&input_path, 2 * 1024 * 1024)?;
        let input = fs::read(input_path).map_err(|error| error.to_string())?;
        verify_case(&input, &manifest, specs[id])?;
        record_pair(&mut pairs, specs[id], &input)?;
    }
    if inventory["family"] == "density" && pairs.len() != 24 {
        return Err("density inventory lacks required LF/space pairs".into());
    }
    verify_pairs(&pairs)?;
    let input_directories = fs::read_dir(root.join("inputs")).map_err(|error| error.to_string())?;
    let mut actual_ids = BTreeSet::new();
    for directory in input_directories {
        let directory = directory.map_err(|error| error.to_string())?;
        if !directory
            .file_type()
            .map_err(|error| error.to_string())?
            .is_dir()
        {
            return Err("input inventory contains a non-directory".into());
        }
        actual_ids.insert(
            directory
                .file_name()
                .into_string()
                .map_err(|_| "non-UTF-8 fixture id")?,
        );
    }
    if actual_ids != ids.into_iter().map(str::to_owned).collect() {
        return Err("input directory inventory differs from declared cases".into());
    }
    println!(
        "verified {} development cases from bytes and literal manifests; no scanner was run",
        cases.len()
    );
    Ok(())
}

pub(super) type PairReceipts = BTreeMap<String, (Option<String>, Option<String>)>;

pub(super) fn record_pair(
    pairs: &mut PairReceipts,
    spec: Spec,
    input: &[u8],
) -> Result<(), String> {
    if let Spec::Density {
        bytes,
        class,
        identity,
        separator,
    } = spec
    {
        let mut normalized = input.to_vec();
        for record in normalized.chunks_exact_mut(64) {
            record[63] = b' ';
        }
        let pair = pairs
            .entry(format!("{bytes}-{class}-{identity}"))
            .or_default();
        let slot = if separator == "lf" {
            &mut pair.0
        } else {
            &mut pair.1
        };
        if slot.replace(sha256_bytes(&normalized)).is_some() {
            return Err("duplicate density pair member".into());
        }
    }
    Ok(())
}

pub(super) fn verify_pairs(pairs: &PairReceipts) -> Result<(), String> {
    for (lf, space) in pairs.values() {
        if !matches!((lf, space), (Some(left), Some(right)) if left == right) {
            return Err("density LF/space inputs differ beyond record separator bytes or lack a counterpart".into());
        }
    }
    Ok(())
}
